import { useState } from "react";

function HienThi({ giaTri }) {
  return <p>Gia tri: {giaTri}</p>;
}

function App() {
  const [so, setSo] = useState(0);
  return (
    <div>
      <HienThi giaTri={so} />
      <button onClick={() => setSo(so + 1)}>Tang</button>
    </div>
  );
}

export default App;
